  @override
  int get hashCode =>
      id.hashCode ^
      versionType.hashCode ^
      releaseTime.hashCode ^
      url.hashCode ^
      isLatestRelease.hashCode ^
      isLatestSnapshot.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is VersionMeta &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          versionType == other.versionType &&
          releaseTime == other.releaseTime &&
          url == other.url &&
          isLatestRelease == other.isLatestRelease &&
          isLatestSnapshot == other.isLatestSnapshot;
}
